window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6d013070178ec519"]={"versions": [{"id": "FIG-6d013070178ec519", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm zur Einordnung des Moduls Diagnostic Log and Trace (DLT) in die AUTOSAR-Schichtenarchitektur. Die Darstellung gliedert sich in eine linke Detailansicht zur Interaktion einer Anwendungs-SWC (<code>App1</code>) über die AUTOSAR Runtime Environment (RTE) mit dem DLT-Kern sowie eine rechte Übersicht zur Einbettung von DLT zwischen Software-Komponenten (<code>App1</code>, <code>App2</code>), Basisschichten und weiteren BSW-Modulen (DEM, DET, DCM, Debug Interface) oberhalb der ECU-Hardware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Applikationsebene</strong>: Software-Komponenten (<code>App1</code>, <code>App2</code>) mit <code>AUTOSAR Int.</code> (AUTOSAR Interface / Port-Schnittstellen).\n</li><li><strong>Laufzeitumgebung</strong>: <code>AUTOSAR RTE</code> als Vermittlungsschicht.\n</li><li><strong>DLT-Modul (Diagnostic Log and Trace)</strong>: Beinhaltet Protokollverarbeitung für <code>DLT Transport/ Storage Protocol</code>, angebunden über <code>Std AUTOSAR Interface</code> bzw. C-APIs.\n</li><li><strong>Benachbarte BSW-Module</strong>:\n<ul class=\"fig-list\"><li><code>DEM</code> (Diagnostic Event Manager): Eingangsverbindung zu DLT.\n</li><li><code>DET</code> (Default Error Tracer): Eingangsverbindung zu DLT.\n</li><li><code>DCM</code> (Diagnostic Communication Manager): Ausgangsverbindung von DLT zur Weiterleitung diagnostischer Daten mit Zugriff auf die <code>ECU-Hardware</code>.\n</li><li><code>Debug Interface</code>: Ausgangsverbindung von DLT zur Hardware-Schnittstelle (<code>ECU-Hardware</code>).\n</li><li>Optionale Senken laut Annotation: <code>CDD</code> (Complex Device Driver) oder serielle Schnittstelle.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Log-/Trace-Meldungserfassung</strong>: Eine Applikation (<code>App1</code>) sendet Log- oder Trace-Informationen über das AUTOSAR-Interface via RTE an das DLT-Modul (schwarzer Pfad).\n</li><li><strong>Formatierung &amp; Pufferung</strong>: DLT sammelt die eingehenden Meldungen und konvertiert sie in ein standardisiertes Format (<code>DLT Transport/ Storage Protocol</code>).\n</li><li><strong>Status-Rückmeldung</strong>: Zur Reduzierung der CPU-Last übermittelt DLT den aktuellen Log-Status über die RTE zurück an die Applikation (blauer Pfad), damit diese das Erzeugen von Logs unterdrücken kann.\n</li><li><strong>Weiterleitung / Ausgabe</strong>: DLT leitet formatierte Datenströme an DCM, Debug-Schnittstelle, CDD oder serielle Schnittstellen zur Übertragung an die ECU-Hardware weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht Anforderungen des AUTOSAR SRS Diagnostic Log and Trace:</p>\n<ul class=\"fig-list\"><li>Bereitstellung standardisierter Schnittstellen für SWCs zur Laufzeitprotokollierung.\n</li><li>Integration von Systemfehlern (DET) und Diagnoseereignissen (DEM) in den DLT-Datenstrom.\n</li><li>Implementierung von Filter- bzw. Log-Status-Rückmeldemechanismen zur Minimierung des Laufzeit-Overheads auf ECU-Ebene.\n</li><li>Flexible Protokollausgabe über Diagnosekanäle (DCM) oder direkte Debug-/Busschnittstellen.\n</li></ul>"}, {"id": "FIG-2ae75aeb92975103", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm zur Einordnung des Moduls Diagnostic Log and Trace (DLT) in die AUTOSAR-Schichtenarchitektur. Die Darstellung gliedert sich in eine linke Detailansicht zur Interaktion einer Anwendungs-SWC (<code>App1</code>) über die AUTOSAR Runtime Environment (RTE) mit dem DLT-Kern sowie eine rechte Übersicht zur Einbettung von DLT zwischen Software-Komponenten (<code>App1</code>, <code>App2</code>), Basisschichten und weiteren BSW-Modulen (DEM, DET, DCM, Debug Interface) oberhalb der ECU-Hardware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Applikationsebene</strong>: Software-Komponenten (<code>App1</code>, <code>App2</code>) mit <code>AUTOSAR Int.</code> (AUTOSAR Interface / Port-Schnittstellen).\n</li><li><strong>Laufzeitumgebung</strong>: <code>AUTOSAR RTE</code> als Vermittlungsschicht.\n</li><li><strong>DLT-Modul (Diagnostic Log and Trace)</strong>: Beinhaltet Protokollverarbeitung für <code>DLT Transport/ Storage Protocol</code>, angebunden über <code>Std AUTOSAR Interface</code> bzw. C-APIs.\n</li><li><strong>Benachbarte BSW-Module</strong>:\n<ul class=\"fig-list\"><li><code>DEM</code> (Diagnostic Event Manager): Eingangsverbindung zu DLT.\n</li><li><code>DET</code> (Default Error Tracer): Eingangsverbindung zu DLT.\n</li><li><code>DCM</code> (Diagnostic Communication Manager): Ausgangsverbindung von DLT zur Weiterleitung diagnostischer Daten mit Zugriff auf die <code>ECU-Hardware</code>.\n</li><li><code>Debug Interface</code>: Ausgangsverbindung von DLT zur Hardware-Schnittstelle (<code>ECU-Hardware</code>).\n</li><li>Optionale Senken laut Annotation: <code>CDD</code> (Complex Device Driver) oder serielle Schnittstelle.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Log-/Trace-Meldungserfassung</strong>: Eine Applikation (<code>App1</code>) sendet Log- oder Trace-Informationen über das AUTOSAR-Interface via RTE an das DLT-Modul (schwarzer Pfad).\n</li><li><strong>Formatierung &amp; Pufferung</strong>: DLT sammelt die eingehenden Meldungen und konvertiert sie in ein standardisiertes Format (<code>DLT Transport/ Storage Protocol</code>).\n</li><li><strong>Status-Rückmeldung</strong>: Zur Reduzierung der CPU-Last übermittelt DLT den aktuellen Log-Status über die RTE zurück an die Applikation (blauer Pfad), damit diese das Erzeugen von Logs unterdrücken kann.\n</li><li><strong>Weiterleitung / Ausgabe</strong>: DLT leitet formatierte Datenströme an DCM, Debug-Schnittstelle, CDD oder serielle Schnittstellen zur Übertragung an die ECU-Hardware weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht Anforderungen des AUTOSAR SRS Diagnostic Log and Trace:</p>\n<ul class=\"fig-list\"><li>Bereitstellung standardisierter Schnittstellen für SWCs zur Laufzeitprotokollierung.\n</li><li>Integration von Systemfehlern (DET) und Diagnoseereignissen (DEM) in den DLT-Datenstrom.\n</li><li>Implementierung von Filter- bzw. Log-Status-Rückmeldemechanismen zur Minimierung des Laufzeit-Overheads auf ECU-Ebene.\n</li><li>Flexible Protokollausgabe über Diagnosekanäle (DCM) oder direkte Debug-/Busschnittstellen.\n</li></ul>"}], "trans": [{"from": "FIG-6d013070178ec519", "to": "FIG-2ae75aeb92975103", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
